from pydantic import BaseModel, Field

class PaperInfo(BaseModel):
    """Information about a single provided paper extracted from its text."""
    title: str | None = Field(description="The full title of this paper as it appears in the document")
    references_other_papers_in_collection: list[str] = Field(
        description="Titles of OTHER provided papers that this document references in its bibliography"
    )

class Parse(BaseModel):
    papers: list[PaperInfo]
